import json, re, unicodedata
SP = r"C:\wt\logos-t423-m8-fable\.ai\scratch\multi_model_bible_chunking\M8_fable\sp_durable"
O = dict(l.split("\t", 1) for l in open(SP + r"\Dan\Dan_oshb.txt", encoding="utf-8").read().split("\n") if "\t" in l)
W = {}; ch = None; cur = None
for l in open(SP + r"\Dan\Dan_web_clean.txt", encoding="utf-8").read().split("\n"):
    m = re.match(r"===== DAN (\d+) =====", l)
    if m: ch = m.group(1); cur = None; continue
    m = re.match(r"\[v\] (\d+) (.*)", l)
    if m: cur = "%s:%s" % (ch, m.group(1)); W[cur] = m.group(2); continue
    if cur and l.strip() and l.strip() != "\u00b6": W[cur] += " " + l.strip()
P = json.load(open(SP + r"\Dan\pmarks_Dan.json", encoding="utf-8"))
def sk(s):
    return "".join(c for c in unicodedata.normalize("NFD", s) if not (0x0591 <= ord(c) <= 0x05C7))
ROOTS = "\u05d0\u05de\u05e8|\u05e2\u05e0\u05d4"
print("OSHB/WLC, Dan.2.27 words 1-5 skeleton:", " ".join(sk(w) for w in O["Dan.2.27"].split(" ")[:5]))
n = 0
for v in range(28, 46):
    r = "Dan.2.%d" % v
    for i, w in enumerate(O[r].split(" ")):
        if re.search(ROOTS, sk(w)):
            n += 1; print("OSHB/WLC token with skeleton", ROOTS, ":", r, "word", i + 1, "of", len(O[r].split(" ")), sk(w))
print("OSHB/WLC tokens in Dan.2.28-Dan.2.45 holding either skeleton:", n)
m = 0
for v in range(28, 46):
    for h in re.finditer(r"\b(said|says|say|answered|answer|replied|spoke|tell|told)\b", W["2:%d" % v]):
        m += 1; print("WEB word:", "2:%d" % v, h.group(0))
print("WEB words (said|says|say|answered|answer|replied|spoke|tell|told) in 2:28-2:45:", m)
mk = [k for k in P["marks"] if k.startswith("Dan.2.") and 36 <= int(k.split(".")[2]) <= 44]
print("OSHB mark layer, marks after any of Dan.2.36-Dan.2.44:", len(mk), mk)
print("OSHB mark layer, mark after Dan.2.45:", P["marks"].get("Dan.2.45"))
